questions.codesnippet:
SELECT club, COUNT(*) FROM memberships
GROUP BY club
HAVING COUNT(*) > 2;

SELECT club, AVG(joined_year) FROM memberships
GROUP BY club
HAVING AVG(joined_year) > 2021;

SELECT joined_year / 10 AS decade, COUNT(*)
FROM memberships
GROUP BY joined_year / 10;

SELECT club, COUNT(*) FROM memberships
GROUP BY club
HAVING COUNT(*) >= 2 AND club <> 'Drama';
